// WF-003: aggregate only non-personal fields (sede, especialidad, tipo de pendiente). Names, phones and reasons are never read.
const zone = 'America/Bogota';
const today = DateTime.now().setZone(zone);
const incidents = [];
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const failed = (items) => items.length === 1 && items[0].json && items[0].json.error;
const note = (items, label) => { const e = items[0].json.error || {}; incidents.push(`${label}: ${e.httpCode || e.status || e.code || e.name || 'error'}`); };
const login = $('Login API').all();
if (failed(login) || !(login[0] && login[0].json.accessToken)) incidents.push('Login: sin token');
const apptItems = $('Citas del dia').all();
const inboxItems = $('Bandeja ADMIN').all();
let approved = [];
if (failed(apptItems)) note(apptItems, 'Citas del día'); else approved = apptItems.map((i) => i.json).filter((a) => a && a.id !== undefined);
let pending = [];
if (failed(inboxItems)) note(inboxItems, 'Bandeja ADMIN'); else pending = inboxItems.map((i) => i.json).filter((p) => p && p.type);
const countBy = (arr, key) => arr.reduce((m, x) => { const k = x[key] || 'Sin dato'; m[k] = (m[k] || 0) + 1; return m; }, {});
const byLocation = countBy(approved, 'locationName');
const bySpecialty = countBy(approved, 'specialtyName');
const pendingSpecialized = pending.filter((p) => p.type === 'SPECIALIZED').length;
const pendingReschedule = pending.filter((p) => p.type === 'RESCHEDULE').length;
const rows = (obj, empty) => Object.entries(obj).map(([k, v]) => `<tr><td>${esc(k)}</td><td style="text-align:right">${v}</td></tr>`).join('') || `<tr><td colspan="2">${empty}</td></tr>`;
const table = (title, head, body) => `<h3>${title}</h3><table border="1" cellpadding="6" cellspacing="0"><tr><th>${head}</th><th>Citas</th></tr>${body}</table>`;
const dateLabel = today.setLocale('es').toFormat("cccc d 'de' LLLL 'de' yyyy");
const html = [
  `<h2>Resumen operativo FCV Citas — ${esc(dateLabel)}</h2>`,
  `<p>Citas APPROVED programadas hoy: <b>${approved.length}</b></p>`,
  table('Por sede', 'Sede', rows(byLocation, 'Sin citas aprobadas hoy')),
  table('Por especialidad', 'Especialidad', rows(bySpecialty, 'Sin citas aprobadas hoy')),
  `<h3>Pendientes de decisión ADMIN</h3><ul><li>Citas especializadas REQUESTED: ${pendingSpecialized}</li><li>Reprogramaciones PENDING: ${pendingReschedule}</li></ul>`,
  '<h3>No disponible por contrato</h3><p>COMPLETED, NO_SHOW y CANCELLED del día: la API no expone un agregado diario por estado (brecha B4).</p>',
  `<h3>Incidencias</h3>${incidents.length ? '<ul>' + incidents.map((i) => `<li>${esc(i)}</li>`).join('') + '</ul>' : '<p>Sin incidencias.</p>'}`,
  '<p style="color:#666">Mensaje automático de laboratorio (FCV Citas). No responder.</p>'
].join('\n');
$execution.customData.set('approvedToday', String(approved.length));
$execution.customData.set('pendingSpecialized', String(pendingSpecialized));
$execution.customData.set('pendingReschedule', String(pendingReschedule));
$execution.customData.set('incidents', String(incidents.length));
return [{ json: {
  subject: `Resumen operativo FCV Citas — ${today.toFormat('yyyy-MM-dd')}${incidents.length ? ' (con incidencias)' : ''}`,
  html,
  approvedToday: approved.length,
  byLocation,
  bySpecialty,
  pendingSpecialized,
  pendingReschedule,
  incidents
} }];
